    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)
    if components:
        smallest = min(len(comp) for comp in components)
        # The unique smallest object is removed.
        for comp in components:
            if len(comp) == smallest:
                for r, c in comp:
                    grid[r][c] = 0
                break
    return grid
